def parse_ports(spec: str) -> list[int]:
    """'22,80,1000-1010' -> lista ordenada de puertos únicos."""
    out = set()
    for part in str(spec).replace(" ", "").split(","):
        if not part:
            continue
        if "-" in part:
            a, b = part.split("-", 1)
            a, b = int(a or 1), int(b or 65535)
            if a > b:
                a, b = b, a
            out.update(range(max(1, a), min(65535, b) + 1))
        else:
            p = int(part)
            if 1 <= p <= 65535:
                out.add(p)
    return sorted(out)


