_etc_services = None


def service_name(port: int, proto: str = "tcp") -> str:
    global _etc_services
    if port in WELL_KNOWN:
        return WELL_KNOWN[port]
    if _etc_services is None:
        _etc_services = {}
        try:
            with open("/etc/services", encoding="utf-8", errors="ignore") as fh:
                for line in fh:
                    line = line.split("#", 1)[0].split()
                    if len(line) >= 2 and "/" in line[1]:
                        p, pr = line[1].split("/", 1)
                        if p.isdigit():
                            _etc_services.setdefault((int(p), pr), line[0])
        except OSError:
            pass
    return _etc_services.get((port, proto), "desconocido")
